namespace sv_0ae00119c3c94edd86dd2f5862b46122.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

/// <summary>
/// Scoped service holding the currently selected warehouse for one user circuit.
/// Fires OnChange when the selection changes so all subscribing components can re-render.
/// </summary>
public class WarehouseState
{
    private string _currentWarehouseId = "wh-1";

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new() { Id = "wh-1", Name = "Warehouse A – Downtown" },
        new() { Id = "wh-2", Name = "Warehouse B – Airport" },
        new() { Id = "wh-3", Name = "Warehouse C – Harbor" }
    ];

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_0ae00119c3c94edd86dd2f5862b46122.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Supports polling with change notification so all subscribers update together.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastCount;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentAlertCount => _lastCount;

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must wrap StateHasChanged
    /// in InvokeAsync because this fires from a background thread.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Start polling every 10 seconds for the given warehouse.
    /// Multiple components can call this; polling starts on the first call.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount > 1) return;
        }

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    /// <summary>
    /// Decrement subscriber count; stop polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount--;
            if (_subscriberCount > 0) return;
        }

        CancelPolling();
    }

    /// <summary>
    /// Restart polling with a new warehouse ID (e.g. when the user switches warehouses).
    /// </summary>
    public void RestartPolling(string warehouseId)
    {
        bool wasPolling;
        int savedCount;
        lock (_lock)
        {
            wasPolling = _subscriberCount > 0;
            savedCount = _subscriberCount;
        }

        if (wasPolling)
        {
            CancelPolling();
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(warehouseId, _cts.Token);
        }
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        // Immediately fetch on start
        await FetchAndNotifyAsync(warehouseId);

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await FetchAndNotifyAsync(warehouseId);
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task FetchAndNotifyAsync(string warehouseId)
    {
        _lastCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        CancelPolling();
    }
}

