@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged" style="max-width: 260px;">
    @foreach (var wh in Services.WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Re-render if another component changes the warehouse
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString() ?? "";
        WarehouseState.SetWarehouse(newId);
        AlertService.RestartPolling(newId);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

@inject Services.InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger ms-2">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success ms-2">0</span>
}

