@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" value="@WarehouseState.SelectedWarehouseId"
        @onchange="OnWarehouseChanged" style="max-width: 280px;">
    @foreach (var wh in WarehouseState.Warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IDisposable

<span class="badge bg-danger rounded-pill ms-2" title="Low stock items">@AlertService.CurrentLowStockCount</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertChanged;
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    private void OnAlertChanged() => InvokeAsync(StateHasChanged);

    private async void OnWarehouseChanged()
    {
        await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertChanged;
        WarehouseState.OnChange -= OnWarehouseChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card border-danger">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 text-danger">@AlertService.CurrentLowStockCount</p>
                <p class="text-muted">Items below minimum level</p>
                <p class="small text-muted">Auto-refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="display-6">@WarehouseState.SelectedWarehouseId</p>
                <p class="text-muted">@WarehouseState.SelectedWarehouseName</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="text-muted">Monitoring inventory levels</p>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;

        // Initial fetch
        await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);

        // Start polling
        _cts = new CancellationTokenSource();
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await _timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on disposal
        }
    }

    private async void OnWarehouseChanged()
    {
        await AlertService.RefreshAsync(WarehouseState.SelectedWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    private void OnAlertChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

